using Aurora.Core;
using System.Numerics;
static class TransportParameterChecks
{
 public static void Run(Action<bool,string> check,Action<Action,string> reject,string? native)
 {
  string script="$TYPE VEHICLETYPE_RAIL_LOCOMOTIVE\n$TRAINSET vagon\n$TRAINSET_REVERSE head\n$TRAINSET vagon\n$UNKNOWN keep\n$END\n";var units=VehicleConsist.Read(script);check(units.Length==3&&units[1].Reverse&&VehicleConsist.Write(script,units)==script,"unchanged mixed trainset order is preserved byte-for-byte");var changed=VehicleConsist.Write(script,[units[1],units[0],units[0]]);check(VehicleConsist.Read(changed).SequenceEqual(new[]{units[1],units[0],units[0]})&&changed.Contains("$UNKNOWN keep"),"train units reorder, repeat and reverse without losing unrelated data");
  reject(()=>VehicleConsist.Write(script,[new("two words")]),"invalid multi-word train reference");
  var model=ObjImporter.Parse("v 0 0 0\nv 1 0 0\nv 0 1 0\nv 1 1 0\no Body\nusemtl Paint\nf 1 2 3\nusemtl Glass\nf 2 4 3\n").Model;var edited=ModelEditing.AssignGroup(model,"Body",1,"Paint");check(model.Nodes[0].Groups[1].Material==1&&edited.Nodes[0].Groups[1].Material==0&&model.Nodes[0].Groups[0]==edited.Nodes[0].Groups[0]&&model.Nodes[0].Indices.SequenceEqual(edited.Nodes[0].Indices),"material assignment can target one draw group without changing geometry or adjacent groups");
  var names=ModelFileNames.Allocate(["C:/source/truck.nmf","C:/a/main.nmf","C:/b/main.nmf"]);check(names.Values.First()=="main.nmf"&&names.Values.Distinct(StringComparer.OrdinalIgnoreCase).Count()==3,"export naming reserves canonical main and disambiguates colliding LOD names");
  var road=new VehicleClass("road-test","VEHICLETYPE_ROAD",null,[],"Road");string airplane="$TYPE VEHICLETYPE_AIRPLANE\n$TAKEOFF_DISTANCE 400\n$PROPELER_STATIC rotor.nmf\n$LANDING_GEAR_ANIM gear.naf\n$FAMILY plane\n$CUSTOM keep\n$MOVEMENT_SPEED 80\n$END\n";string roadScript=VehicleCatalog.ApplyClass(airplane,road);check(!VehicleScript.Fields(roadScript).Any(f=>f.Key is "TAKEOFF_DISTANCE" or "PROPELER_STATIC" or "LANDING_GEAR_ANIM" or "FAMILY")&&roadScript.Contains("$CUSTOM keep")&&roadScript.Contains("$MOVEMENT_SPEED 80"),"type change clears recognized incompatible aircraft data while preserving unknown and shared fields");
  var cabin=new VehicleClass("cabin-test","VEHICLETYPE_CABIN",null,["CABIN_LIGHT"],"Cabin");string cabinScript=VehicleCatalog.ApplyClass(roadScript.Replace("$END","$MOVEMENT_EMPTY_WEIGHT 0.52\n$END"),cabin);check(!VehicleScript.Fields(cabinScript).Any(f=>f.Key=="MOVEMENT_SPEED")&&cabinScript.Contains("$CUSTOM keep")&&cabinScript.Contains("$MOVEMENT_EMPTY_WEIGHT 0.52"),"cabin type does not inherit road movement fields");
  string layered="$TYPE VEHICLETYPE_ROAD\n$SOUND_PARAMS sounds/engine.ini // keep\n$SOUND_PARAMS_WORKSHOP \"custom horn.ini\"\n$SOUND_PARAMS sounds/tyres.ini\n$END\n$SOUND_PARAMS_WORKSHOP ignored.ini\n";var soundLayers=VehicleSoundFiles.Layers(layered);check(soundLayers.Length==3&&soundLayers[1].Workshop&&VehicleSoundFiles.SetLayers(layered,soundLayers)==layered,"unchanged ordered sound layers preserve comments and quoted paths");string mapped=VehicleSoundFiles.Map(layered,r=>"assets/"+r);check(mapped.Contains("\"assets/custom horn.ini\"")&&mapped.Contains("$SOUND_PARAMS_WORKSHOP ignored.ini"),"sound asset remapping respects terminator and paths containing spaces");check(VehicleSoundFiles.Overlaps(["$TEXT sound_horn first\n","$TEXT sound_horn second\n$FLOAT wobble 1\n"]).SequenceEqual(new[]{"sound_horn"})&&VehicleSoundFiles.MissingEvents("$TEXT sound_horn missing\n$TEXT sound_engine known\n",new HashSet<string>{"known"}).SequenceEqual(new[]{"missing"}),"sound diagnostics distinguish overlapping layer parameters and unavailable registered events");
  var rotor=VehicleParts.Read("$TYPE VEHICLETYPE_HELICOPTER\n$PROPELER_HELICOPTER 2 static.nmf high.nmf low.nmf rotor.mtl\n$PROPELER_HELICOPTER_POINT_DIR 1 2 3 0 0 1.57079632679\n$END\n").Single();check(rotor.Model=="static.nmf"&&rotor.Material=="rotor.mtl"&&Vector3.Distance(Vector3.Transform(Vector3.UnitX,rotor.Transform),new(1,4,3))<1e-5f,"helicopter static assembly applies scale, native radians and placement");
  string assembly="$TYPE VEHICLETYPE_CABIN\n$CRANE_STATIC bucket.nmf\n$CRANE_DYNAMIC trolley.nmf 1 2 3\n$END\n";check(VehicleParts.HasCabinAssembly(assembly)&&VehicleParts.Read(assembly).Length==0,"cabin purchase model does not duplicate working bucket");var working=VehicleParts.Read(assembly,true);check(working.Length==2&&working[0].Model=="bucket.nmf"&&working[1].Model=="trolley.nmf"&&Vector3.Transform(Vector3.Zero,working[1].Transform)==new Vector3(1,2,3),"cabin working frame includes bucket and trolley with native placement");check(!VehicleParts.HasCabinAssembly(assembly.Replace("$CRANE_DYNAMIC","$UNKNOWN"))&&VehicleParts.Read(assembly.Replace("VEHICLETYPE_CABIN","VEHICLETYPE_ROAD")).Single().Model=="bucket.nmf","incomplete cabin does not hide main model and road crane keeps purchase part");
  string wheelScript="$TYPE VEHICLETYPE_AIRPLANE\n$MOVEMENT_WHEEL_FRONT\n1 2 3 // annotation\n$MOVEMENT_WHEEL_BACK 0 -1000 0\n$END\n";string wheelMoved=VehicleLights.Transform(wheelScript,Matrix4x4.CreateTranslation(4,5,6));var wheelTokens=VehicleScript.Tokens(wheelMoved).Where(t=>t.Key=="MOVEMENT_WHEEL_FRONT").Select(t=>t.Value).ToArray();check(wheelTokens.SequenceEqual(new[]{"5","7","9"})&&wheelMoved.Contains("// annotation")&&wheelMoved.Contains("$MOVEMENT_WHEEL_BACK 0 -1000 0"),"pivot baking transforms aircraft support points, preserves annotations and disabled sentinels");reject(()=>VehicleLights.Transform("$TYPE VEHICLETYPE_ROAD\n$MOVEMENT_UNKNOWN_POINT 1 2 3\n$END\n",Matrix4x4.CreateTranslation(1,0,0)),"unknown movement section cannot bypass pivot safety checks");
  if(native==null||VehicleAssets.Media(Path.GetDirectoryName(native)??native) is not string media)return;
  string[] roots=["vehicles","trains","ships","airplanes","helicopters","cabins"];var bases=new[]{media}.Concat(Directory.GetDirectories(media).Where(d=>Path.GetFileName(d).StartsWith("dlc",StringComparison.OrdinalIgnoreCase)||Path.GetFileName(d).StartsWith("elc",StringComparison.OrdinalIgnoreCase)));int verified=0;var failures=new List<string>();
  foreach(string folder in bases.SelectMany(b=>roots.Select(r=>Path.Combine(b,r))).Where(Directory.Exists))foreach(string file in Directory.EnumerateFiles(folder,"script.ini",SearchOption.AllDirectories)){
   string text=File.ReadAllText(file);try{VehicleParts.Read(text);if(VehicleParts.HasCabinAssembly(text)){var parts=VehicleParts.Read(text,true);foreach(var part in parts){string path=VehicleAssets.Resolve(part.Model,Path.GetDirectoryName(file)!,media);_=new NativeModel(File.ReadAllBytes(path));}verified++;}}catch(Exception ex){failures.Add(Path.GetRelativePath(media,file)+" parts: "+ex.Message);}try{if(VehicleLights.Write(text,VehicleLights.Read(text))!=text)throw new Exception("unchanged lamp data changed");}catch(Exception ex){failures.Add(Path.GetRelativePath(media,file)+" lights: "+ex.Message);}foreach(var field in VehicleScript.Fields(text)){var spec=TransportParameters.All.FirstOrDefault(p=>p.Key==field.Key)?.For(text,field.Occurrence);if(spec==null){try{if(field.Key is "RESOURCE_VISUALIZATION" or "RESOURCE_VISUALIZATION_JOINT" or "RESOURCE_VISUALIZATION_BONE"){var layout=VehicleScript.Cargo(text,field.Occurrence,field.Key);if(VehicleScript.SetCargo(text,layout,field.Occurrence,field.Key)!=text)throw new Exception("cargo bytes changed");verified++;}else if(field.Key is "CARGOVEHICLE_VISUALIZATION" or "CARGOVEHICLE_VISUALIZATION_JOINT"){var box=VehicleCargoBox.Read(text,field.Key,field.Occurrence);if(VehicleCargoBox.Write(text,field.Key,field.Occurrence,box)!=text)throw new Exception("platform bytes changed");verified++;}}catch(Exception ex){failures.Add(Path.GetRelativePath(media,file)+" "+field.Key+": "+ex.Message);}continue;}try{var args=spec.Read(text,field.Occurrence);if(spec.Write(text,field.Occurrence,args)!=text)throw new Exception("unchanged bytes changed");verified++;}catch(Exception ex){failures.Add(Path.GetRelativePath(media,file)+" "+field.Key+": "+ex.Message);}}
  }
  if(failures.Count>0)throw new Exception("Typed transport layout failures: "+string.Join("; ",failures.Take(8)));
  check(verified>500,"typed linked models, mechanisms, vehicle points and class fields roundtrip native layouts: "+verified);
 }
}
